    // VM bank backdoor (cells of the bank's real SRAM macro models; layout of ot_sram_1r1w_1024x256_m2_r2c2: MUX 2)
    function automatic [6:0] vchk(input [31:0] d);
        integer i, j, a0, b0, c0, n; reg [6:0] c, col; reg [31:0] rm;
        begin
            c = 0;
            for (j = 0; j < 7; j = j + 1) begin
                rm = 0; n = 0;
                for (a0 = 0; a0 < 7; a0 = a0 + 1) for (b0 = a0 + 1; b0 < 7; b0 = b0 + 1) for (c0 = b0 + 1; c0 < 7; c0 = c0 + 1) begin
                    if (n < 32) begin col = (7'd1 << a0) | (7'd1 << b0) | (7'd1 << c0); rm[n] = col[j]; end
                    n = n + 1;
                end
                c[j] = ^(d & rm);
            end
            vchk = c;
        end
    endfunction
    task automatic vm_cell(input integer bk, input integer mac, input integer a, input integer bit_i, input reg v);
        case (bk)
            0: case (mac) 0: dut.vmb_SW0.u_ot_pr_core.bank.u_a.arr[a/2][bit_i*2 + a%2] = v; 1: dut.vmb_SW0.u_ot_pr_core.bank.u_b.arr[a/2][bit_i*2 + a%2] = v; default: dut.vmb_SW0.u_ot_pr_core.bank.u_c.arr[a/2][bit_i*2 + a%2] = v; endcase
